<?php

namespace App\Database\Seeds;

use CodeIgniter\Database\Seeder;

/**
 * MasterJraSeeder
 *
 * Seeder lengkap Kode Klasifikasi Arsip dan Jadwal Retensi Arsip (JRA)
 * berdasarkan Lampiran Peraturan Bupati Buleleng Nomor 41 Tahun 2024
 * tentang Klasifikasi Arsip, Jadwal Retensi Arsip, dan Sistem Klasifikasi
 * Keamanan dan Akses Arsip Dinamis Lingkungan Pemerintah Daerah (423 Halaman).
 *
 * Total Data:
 * - 2.987 Kode Klasifikasi (543 Induk Klasifikasi + 2.444 Sub-Klasifikasi JRA)
 * - 2.444 Jadwal Retensi Arsip (JRA) lengkap beserta keamanan, hak akses,
 *   akses publik, dasar pertimbangan, dan unit pengolah.
 *
 * Cara menjalankan:
 *   php spark db:seed MasterJraSeeder
 */
class MasterJraSeeder extends Seeder
{
    private function uuidv4(): string
    {
        $data = random_bytes(16);
        $data[6] = chr(ord($data[6]) & 0x0f | 0x40);
        $data[8] = chr(ord($data[8]) & 0x3f | 0x80);
        return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($data), 4));
    }

    public function run()
    {
        $dataset = $this->getDataset();
        $baseTime = strtotime('2026-01-01 00:00:00');

        // Ambil data existing agar idempotent & tidak merusak relasi FK pada tabel arsip
        $existingKlasRows = $this->db->table('kode_klasifikasi')->select('id_kode_klasifikasi, kode')->get()->getResultArray();
        $existingKlasMap = [];
        foreach ($existingKlasRows as $row) {
            $existingKlasMap[trim((string) $row['kode'])] = $row['id_kode_klasifikasi'];
        }

        $existingJraRows = $this->db->table('jra')->select('id_jra, id_kode_klasifikasi')->get()->getResultArray();
        $existingJraMap = [];
        foreach ($existingJraRows as $row) {
            $existingJraMap[$row['id_kode_klasifikasi']] = $row['id_jra'];
        }

        $klasToInsert = [];
        $klasToUpdate = [];
        $jraToInsert  = [];
        $jraToUpdate  = [];

        foreach ($dataset as $idx => $item) {
            $kode = $item['kode'];
            $timestamp = date('Y-m-d H:i:s', $baseTime + $idx);

            if (isset($existingKlasMap[$kode])) {
                $idKlasifikasi = $existingKlasMap[$kode];
                $klasToUpdate[] = [
                    'id_kode_klasifikasi' => $idKlasifikasi,
                    'kode'                => $kode,
                    'nama_klasifikasi'    => $item['nama_klasifikasi'],
                    'deskripsi'           => $item['deskripsi'],
                    'created_at'          => $timestamp,
                    'updated_at'          => $timestamp,
                ];
            } else {
                $idKlasifikasi = $this->uuidv4();
                $existingKlasMap[$kode] = $idKlasifikasi;
                $klasToInsert[] = [
                    'id_kode_klasifikasi' => $idKlasifikasi,
                    'kode'                => $kode,
                    'nama_klasifikasi'    => $item['nama_klasifikasi'],
                    'deskripsi'           => $item['deskripsi'],
                    'created_at'          => $timestamp,
                    'updated_at'          => $timestamp,
                ];
            }

            if (!empty($item['jra'])) {
                $jra = $item['jra'];
                if (isset($existingJraMap[$idKlasifikasi])) {
                    $jraToUpdate[] = [
                        'id_jra'               => $existingJraMap[$idKlasifikasi],
                        'id_kode_klasifikasi'  => $idKlasifikasi,
                        'retensi_aktif'        => $jra['retensi_aktif'],
                        'retensi_inaktif'      => $jra['retensi_inaktif'],
                        'keterangan_retensi'   => $jra['keterangan_retensi'],
                        'klasifikasi_keamanan' => $jra['klasifikasi_keamanan'],
                        'hak_akses'            => $jra['hak_akses'],
                        'akses_publik'         => $jra['akses_publik'],
                        'dasar_pertimbangan'   => $jra['dasar_pertimbangan'],
                        'unit_pengolah'        => $jra['unit_pengolah'],
                        'created_at'           => $timestamp,
                        'updated_at'           => $timestamp,
                    ];
                } else {
                    $idJra = $this->uuidv4();
                    $existingJraMap[$idKlasifikasi] = $idJra;
                    $jraToInsert[] = [
                        'id_jra'               => $idJra,
                        'id_kode_klasifikasi'  => $idKlasifikasi,
                        'retensi_aktif'        => $jra['retensi_aktif'],
                        'retensi_inaktif'      => $jra['retensi_inaktif'],
                        'keterangan_retensi'   => $jra['keterangan_retensi'],
                        'klasifikasi_keamanan' => $jra['klasifikasi_keamanan'],
                        'hak_akses'            => $jra['hak_akses'],
                        'akses_publik'         => $jra['akses_publik'],
                        'dasar_pertimbangan'   => $jra['dasar_pertimbangan'],
                        'unit_pengolah'        => $jra['unit_pengolah'],
                        'created_at'           => $timestamp,
                        'updated_at'           => $timestamp,
                    ];
                }
            }
        }

        $this->db->transStart();

        if (!empty($klasToUpdate)) {
            foreach (array_chunk($klasToUpdate, 500) as $chunk) {
                $this->db->table('kode_klasifikasi')->updateBatch($chunk, 'id_kode_klasifikasi');
            }
        }
        if (!empty($klasToInsert)) {
            foreach (array_chunk($klasToInsert, 500) as $chunk) {
                $this->db->table('kode_klasifikasi')->insertBatch($chunk);
            }
        }
        if (!empty($jraToUpdate)) {
            foreach (array_chunk($jraToUpdate, 500) as $chunk) {
                $this->db->table('jra')->updateBatch($chunk, 'id_jra');
            }
        }
        if (!empty($jraToInsert)) {
            foreach (array_chunk($jraToInsert, 500) as $chunk) {
                $this->db->table('jra')->insertBatch($chunk);
            }
        }

        $this->db->transComplete();

        if (is_cli()) {
            echo sprintf(
                "MasterJraSeeder selesai: kode_klasifikasi (insert: %d, update: %d), jra (insert: %d, update: %d)\n",
                count($klasToInsert),
                count($klasToUpdate),
                count($jraToInsert),
                count($jraToUpdate)
            );
        }
    }

